code_examples.code:
.parent { position: relative; }
.child {
  position: absolute;
  top: 50px;    /* from the parent's top edge */
  left: 50px;
  z-index: -1;  /* sits behind other content */
}

solution_code.code:
.red-circle {
  background-color: red;
  width: 200px;
  height: 200px;
  border-radius: 50%;
  position: absolute;
  top: 150px;
  left: 250px;
}

